# The gateway's holidays, seeded with two demo entries (idempotent). Bare
# except on purpose — Jython's 'except Exception' misses Java exceptions.
import sys
log = system.util.getLogger('HolidayDemo')
from com.inductiveautomation.ignition.common.user.schedule import HolidayModel
def ensure(name, dateStr, repeat):
	try:
		if name not in [str(n) for n in system.user.getHolidayNames()]:
			d = system.date.parse(dateStr, 'yyyy-MM-dd')
			try:
				m = HolidayModel(name, d, repeat)
			except:
				m = HolidayModel()
				m.name = name
				m.date = d
				m.repeatAnnually = repeat
			resp = system.user.addHoliday(m)
			for err in resp.getErrors():
				log.warn('addHoliday(' + name + '): ' + str(err))
	except:
		log.warn('ensure(' + name + ') failed: ' + str(sys.exc_info()[1]))
ensure('Demo New Year', '2020-01-01', True)
ensure('Demo Founders Day', '2026-09-01', False)
out = []
for h in system.user.getHolidays():
	try:
		out.append({'name': str(h.name), 'date': system.date.format(h.date, 'yyyy-MM-dd') if h.date else '', 'repeatAnnually': bool(h.repeatAnnually)})
	except:
		log.warn('map holiday failed: ' + str(sys.exc_info()[1]))
return out

